<template>
  <div class="chart-card" :class="{ 'glow-border': chartInfo[7] }">
    <!-- 只有一张曲绘时就是普通图片；多张时叠两层做淡入淡出 -->
    <img v-if="!rotating" :src="chartInfo[2]" alt="" class="cover-img" loading="lazy" />
    <template v-else>
      <img
        :src="layers[0]"
        alt=""
        class="cover-img cover-layer"
        :class="{ 'is-active': active === 0 }"
        loading="lazy"
      />
      <img
        :src="layers[1]"
        alt=""
        class="cover-img cover-layer"
        :class="{ 'is-active': active === 1 }"
        loading="lazy"
      />
    </template>
    <div class="card-shade"></div>

    <span class="top-right-text">{{ chartInfo[6] }}</span>

    <div class="card-info">
      <h3 class="chart-name">{{ chartInfo[3] }}</h3>
      <span
        class="dt-chip difficulty-tag"
        :style="{ '--chip-color': chartInfo[5] || 'var(--dt-text-dim)' }"
      >{{ chartInfo[4] + " Lv." + chartInfo[1].toFixed(1) }}</span>
    </div>

    <div class="bottom-left-info">
      <img src="/assets/rank/Phi.png" class="info-icon" alt="Phi" />
      <div class="info-text-wrapper">
        <div class="main-text">1000000</div>
        <div class="sub-text">100.00%</div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, onUnmounted, ref, watch } from 'vue'

/*
 * B30 卡片：曲绘铺底 + 左上曲名 + 右下难度标签 + 左下成绩。
 * chartInfo 字段顺序由 api/levels.js 决定：
 * [0] 曲名ID, [1] 定数, [2] 曲绘, [3] 曲名, [4] 难度名, [5] 难度色, [6] 右上角文字, [7] 是否高亮边框。
 * 成绩那两块目前固定写死 1000000 / 100.00%（没有接入真实成绩，只做展示）。
 * covers 可选：同一版里有多张曲绘时（愚人节差分图）每 5 秒轮换一张，切换用淡入淡出。
 */
const props = defineProps({
  chartInfo: {
    type: Array,
    required: true
  },
  covers: {
    type: Array,
    default: null
  }
})

// 两张叠图各存一张曲绘，active 指向当前可见的那层；轮换时让另一层换成下一张再翻过去
const layers = ref(['', ''])
const active = ref(0)
const index = ref(0)
let timer = null

const rotating = computed(() => Boolean(props.covers && props.covers.length > 1))

const stop = () => {
  if (timer) {
    clearInterval(timer)
    timer = null
  }
}

const advance = () => {
  if (!rotating.value) return
  index.value = (index.value + 1) % props.covers.length
  const back = 1 - active.value
  const next = layers.value.slice()
  next[back] = props.covers[index.value]
  layers.value = next
  active.value = back
}

const start = () => {
  stop()
  index.value = 0
  active.value = 0
  if (rotating.value) {
    // 两张图一开始就都挂上，第二张会立刻加载，轮到它时不会空一帧
    layers.value = [props.covers[0], props.covers[1 % props.covers.length]]
    timer = setInterval(advance, 5000)
  } else {
    layers.value = [props.chartInfo[2], props.chartInfo[2]]
  }
}

watch(() => props.covers, start, { immediate: true })
onUnmounted(stop)
</script>

